CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT (current_setting('request.jwt.claims',true)::jsonb->>'sub')::uuid $$;
CREATE TABLE auth.users(id uuid PRIMARY KEY, email text, raw_user_meta_data jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id),role text);
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE FUNCTION public.act_as(p_user uuid) RETURNS text LANGUAGE plpgsql AS $$ DECLARE old text:=current_setting('request.jwt.claims',true); BEGIN PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p_user)::text,true); RETURN old; END $$;
CREATE TABLE public.economy_config(key text PRIMARY KEY,value jsonb);
CREATE FUNCTION public.economy_number(text) RETURNS numeric LANGUAGE sql AS $$ SELECT (value#>>'{}')::numeric FROM economy_config WHERE key=$1 $$;
CREATE TABLE public.companies(id uuid PRIMARY KEY,user_id uuid,name text,icao_code text,home_base_icao text,is_personal boolean DEFAULT false,is_supporter boolean DEFAULT false,next_flight_sequence bigint DEFAULT 101,prev_week_rank integer,is_hiring boolean DEFAULT false,stake_offer_pct numeric DEFAULT 0,next_dividend_at timestamptz);
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),roster_company_id uuid REFERENCES companies(id),roster_joined_at timestamptz);
CREATE TABLE public.fleet_aircraft(id uuid PRIMARY KEY,company_id uuid REFERENCES companies(id),status text,ownership text DEFAULT 'OWNED',returned_at timestamptz,reserved_by uuid,reserved_until timestamptz,location_icao text);
CREATE TABLE public.flights(id uuid PRIMARY KEY,company_id uuid REFERENCES companies(id),aircraft_id uuid REFERENCES fleet_aircraft(id),status text,pilot_id uuid,passengers integer DEFAULT 0,origin_icao text,flight_number text,estimate jsonb DEFAULT '{}');
CREATE TABLE public.special_missions(id uuid PRIMARY KEY,flight_id uuid REFERENCES flights(id),accepted_by uuid,status text);
CREATE TABLE public.used_aircraft_listings(id uuid PRIMARY KEY,seller_company_id uuid REFERENCES companies(id),buyer_company_id uuid REFERENCES companies(id),fleet_aircraft_id uuid REFERENCES fleet_aircraft(id));
CREATE TABLE public.lease_contracts(id uuid PRIMARY KEY,company_id uuid REFERENCES companies(id),aircraft_id uuid REFERENCES fleet_aircraft(id));
CREATE TABLE public.company_fobs(id uuid PRIMARY KEY,company_id uuid REFERENCES companies(id));
CREATE TABLE public.company_stakes(id uuid PRIMARY KEY,company_id uuid REFERENCES companies(id),holder_id uuid REFERENCES profiles(id));
CREATE TABLE public.leaderboard_weekly_snapshots(company_id uuid REFERENCES companies(id));
CREATE TABLE public.company_ledger(id bigint GENERATED ALWAYS AS IDENTITY,company_id uuid REFERENCES companies(id),entry_type text,debit_account text,credit_account text,amount numeric,company_delta numeric,balance_after numeric,description text,reference text,idempotency_key text UNIQUE);
CREATE TABLE public.pilot_ledger(id bigint GENERATED ALWAYS AS IDENTITY,user_id uuid REFERENCES profiles(id),amount numeric);
CREATE FUNCTION public.company_balance(uuid) RETURNS numeric LANGUAGE sql AS $$ SELECT coalesce((SELECT balance_after FROM company_ledger WHERE company_id=$1 AND EXISTS(SELECT 1 FROM companies WHERE id=$1 AND user_id=auth.uid()) ORDER BY id DESC LIMIT 1),0) $$;
CREATE FUNCTION public.company_post(p_company uuid,p_type text,p_debit text,p_credit text,p_delta numeric,p_desc text,p_ref text,p_key text) RETURNS numeric LANGUAGE plpgsql AS $$ DECLARE bal numeric; BEGIN bal:=company_balance(p_company)+p_delta; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(p_company,p_type,p_debit,p_credit,abs(p_delta),p_delta,bal,p_desc,p_ref,p_key); RETURN bal; END $$;
CREATE FUNCTION public.ledger_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ledger entries are immutable'; END $$;
CREATE TRIGGER ledger_no_update BEFORE UPDATE OR DELETE ON company_ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
CREATE TRIGGER pilot_ledger_immutable BEFORE UPDATE OR DELETE ON pilot_ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
CREATE TABLE public.airport_fuel_pools(airport_icao text,fuel_type text,stock_gal numeric,updated_at timestamptz);
CREATE TABLE public.airport_passenger_pools(airport_icao text,stock numeric,updated_at timestamptz);
CREATE FUNCTION public.airport_fuel_capacity(text,text) RETURNS numeric LANGUAGE sql AS $$ SELECT 1000::numeric $$;
CREATE FUNCTION public.airport_fuel_stock(text,text) RETURNS numeric LANGUAGE sql AS $$ SELECT stock_gal FROM airport_fuel_pools WHERE airport_icao=$1 AND fuel_type=$2 $$;
CREATE FUNCTION public.passenger_stock(text) RETURNS numeric LANGUAGE sql AS $$ SELECT stock FROM airport_passenger_pools WHERE airport_icao=$1 $$;
CREATE FUNCTION public.admin_players() RETURNS TABLE(user_id uuid,username text,email text,company_name text,icao_code text,balance numeric,fleet_count bigint,joined_at timestamptz) LANGUAGE plpgsql AS $$ BEGIN RETURN QUERY SELECT u.id,u.email,u.email,c.name,c.icao_code,0::numeric,0::bigint,u.created_at FROM auth.users u LEFT JOIN public.companies c ON c.user_id=u.id; END $$;
CREATE FUNCTION public.admin_company_supporters() RETURNS TABLE(company_id uuid,user_id uuid,is_supporter boolean) LANGUAGE plpgsql AS $$ BEGIN RETURN QUERY SELECT c.id,c.user_id,c.is_supporter FROM public.companies c; END $$;